await mkdir(directory, { recursive: true });
const plans = await Promise.all(Array.from({ length: 16 }, async (_, index) => {
  const start = index * chunk;
  const length = Math.min(chunk, total - start);
  const prefix = Math.min((await stat(`${original}/${index}.part`)).size, length);
  const tails = [];
  for (let at = prefix; at < length; at += 1048576) tails.push({ start: start + at, end: Math.min(start + at + 1048575, start + length - 1), path: `${directory}/${index}-${at}.part` });
  return { index, prefix, tails };
}));
const jobs = plans.flatMap(plan => plan.tails);
let next = 0;
let complete = 0;
console.log(`Reusing verified range prefixes; fetching ${jobs.length} smaller remaining ranges.`);
await Promise.all(Array.from({ length: Math.min(48, jobs.length) }, async () => {
  while (next < jobs.length) {
    const job = jobs[next++];
