import { GRID_SIZES, isValidSize } from '../deck.ts';
import { MOVES_MAX } from '../game.ts';
import { isJsonObject, isNonnegativeSafeInteger, parseJson } from '../saved-format.ts';

export const DEFAULT_SIZE = GRID_SIZES[0];
export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export const PREFERENCES_VERSION = 1;
export interface Preferences {
  readonly size: number;
  readonly bestMoves: Readonly<Record<string, number>>;
}
export interface PreferenceStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export function readPreferences(store: PreferenceStore | null): Preferences {
  const fallback: Preferences = { size: DEFAULT_SIZE, bestMoves: {} };
  try {
    const text = store?.getItem(PREFERENCES_KEY);
    if (!text) return fallback;
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      value.schemaVersion !== PREFERENCES_VERSION ||
      typeof value.size !== 'number'
    )
      return fallback;
    if (!isValidSize(value.size) || !isJsonObject(value.bestMoves)) return fallback;
    const bestMoves: Record<string, number> = {};
    for (const [size, moves] of Object.entries(value.bestMoves)) {
      const numberSize = Number(size);
      if (
        String(numberSize) !== size ||
        !isValidSize(numberSize) ||
        !isNonnegativeSafeInteger(moves) ||
        moves > MOVES_MAX ||
        moves < numberSize ** 2 / 2
      )
        return fallback;
      bestMoves[size] = moves;
    }
    return { size: value.size, bestMoves };
  } catch {
    return fallback;
  }
}

export function writePreferences(store: PreferenceStore | null, preferences: Preferences): void {
  try {
    store?.setItem(
      PREFERENCES_KEY,
      JSON.stringify({ schemaVersion: PREFERENCES_VERSION, ...preferences }),
    );
  } catch {
    // A blocked browser store doesn't stop the current game.
  }
}

export function rememberBest(preferences: Preferences, size: number, moves: number): Preferences {
  return { ...preferences, bestMoves: { ...preferences.bestMoves, [size]: moves } };
}
import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { StatusLabel } from './status-labels.ts';
import type { GameState } from '../game.ts';
import './status.css';

interface GameStatusProps {
  game: GameState;
  best: number | undefined;
  celebration: boolean;
}

export function GameStatus({ game, best, celebration }: GameStatusProps) {
  return (
    <>
      <dl className="stats">
        <div>
          <dt>{StatusLabel.moves}</dt> <dd>{game.moves}</dd>
        </div>
        <div>
          <dt>{StatusLabel.pairs}</dt>{' '}
          <dd>
            {game.matched.length / 2}/{game.deck.length / 2}
          </dd>
        </div>
        <div>
          <dt>{StatusLabel.time}</dt> <dd>{formatElapsed(game.elapsedMs)}</dd>
        </div>
        <div>
          <dt>{StatusLabel.best}</dt> <dd>{best ?? 0}</dd>
        </div>
      </dl>
      {isWon(game) && (
        <p className={`victory${celebration ? ' celebrate' : ''}`}>
          Every pair found in {game.moves} moves and {formatElapsed(game.elapsedMs)}. Well played.
        </p>
      )}
    </>
  );
}
import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
import { SPEC_VECTOR } from '../game.fixture.ts';
import type { PreferenceStore } from './storage.ts';

function memoryStore(initial = ''): PreferenceStore {
  const entries = new Map([[PREFERENCES_KEY, initial]]);
  return {
    getItem: (key) => entries.get(key) ?? null,
    setItem: (key, value) => {
      entries.set(key, value);
    },
  };
}

test('preferences round trip size and separate minimum moves per size', () => {
  const store = memoryStore();
  const preferences = rememberBest(rememberBest({ size: 6, bestMoves: {} }, 4, 12), 6, 20);
  writePreferences(store, preferences);
  assert.deepEqual(readPreferences(store), preferences, 'R10 scores survive storage round trip');
  assert.equal(rememberBest(preferences, 4, 13), preferences, 'R10 worse score keeps best');
  assert.equal(rememberBest(preferences, 4, 12), preferences);
  assert.equal(rememberBest(preferences, 4, 9).bestMoves['4'], 9, 'R10 better score replaces best');
  assert.equal(preferences.bestMoves['6'], 20, 'R10 size six has its separate best');
});

test('a best at the move cap round trips and a larger saved best is ignored', () => {
  const store = memoryStore();
  const capped = { size: DEFAULT_SIZE, bestMoves: { [DEFAULT_SIZE]: MOVES_MAX } };
  writePreferences(store, capped);
  assert.deepEqual(readPreferences(store), capped);
  assert.equal(rememberBest(capped, DEFAULT_SIZE, MOVES_MAX), capped);
  const larger = {
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: MOVES_MAX + 1 },
  };
  store.setItem(PREFERENCES_KEY, JSON.stringify(larger));
  assert.deepEqual(readPreferences(store), { size: DEFAULT_SIZE, bestMoves: {} });
});

const INVALID_PREFERENCES = [
  '{',
  'null',
  '{}',
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 5, bestMoves: {} }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: -1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 8.5 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { '04': 8 } }),
];
for (const [index, text] of INVALID_PREFERENCES.entries()) {
  test(`preferences ignore invalid saved data ${index + 1}`, () => {
    assert.deepEqual(readPreferences(memoryStore(text)), { size: DEFAULT_SIZE, bestMoves: {} });
  });
}

test('storage failures keep play available and never change unrelated keys', () => {
  const denied: PreferenceStore = {
    getItem: () => {
      throw new Error();
    },
    setItem: () => {
      throw new Error();
    },
  };
  assert.equal(DEFAULT_SIZE, SPEC_VECTOR.sizes[0]);
  assert.equal(readPreferences(denied).size, DEFAULT_SIZE);
  assert.doesNotThrow(() => writePreferences(denied, { size: DEFAULT_SIZE, bestMoves: {} }));
  assert.equal(readPreferences(null).size, DEFAULT_SIZE);
  const store = memoryStore();
  const unrelated = 'another-application';
  store.setItem(unrelated, 'kept');
  writePreferences(store, { size: DEFAULT_SIZE, bestMoves: {} });
  assert.equal(store.getItem(unrelated), 'kept');
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadTimedBoard, exportedSnapshot, finishBoard, loadFixedBoard } from './game-fixture.ts';
import { PREFERENCES_KEY } from '../src/game/session/storage.ts';

test('better equal and worse completed scores persist after each reload', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  for (const [misses, expected] of [
    [2, 10],
    [1, 9],
    [1, 9],
    [3, 9],
  ]) {
    if (misses === undefined || expected === undefined) throw new Error('Missing score case');
    await page.locator('summary').click();
    await page.getByLabel(ReproductionControl.board, { exact: true }).fill('np1-4-1');
    await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
    await page.locator('summary').click();
    for (let miss = 0; miss < misses; miss++) {
      await page.locator('.card').nth(0).click();
      await page.locator('.card').nth(1).click();
      await page.clock.runFor(800);
    }
    for (const pair of EXAMPLE_PAIRS)
      for (const index of pair) await page.locator('.card').nth(index).click();
    await expect(page.locator('.stats dd').nth(3)).toHaveText(String(expected));
    await page.reload();
    await expect(page.locator('.stats dd').nth(3)).toHaveText(String(expected));
    expect(await exportedSnapshot(page)).toMatchObject({
      matched: [],
      moves: 0,
      elapsedMs: 0,
      started: false,
      selection: { kind: 'closed' },
    });
  }
});

test('snapshot loads save only a valid size and every reload starts fresh', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  await page.locator('summary').click();
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  const valid = {
    version: 1,
    boardCode: 'np1-6-1',
    matched: [],
    moves: 0,
    elapsedMs: 2000,
    started: true,
    selection: { kind: 'one', index: 5 },
  };
  await field.fill(JSON.stringify(valid));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
  await page.reload();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
  expect(await exportedSnapshot(page)).toMatchObject({
    matched: [],
    moves: 0,
    elapsedMs: 0,
    started: false,
    selection: { kind: 'closed' },
  });
  await page.locator('summary').click();
  await field.fill(JSON.stringify({ ...valid, boardCode: 'np1-8-1', extra: true }));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.reload();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
});

test('saved size and per-size completed bests survive reload and resets', async ({
  page,
  gameURL,
}) => {
  await loadFixedBoard(page, gameURL);
  await finishBoard(page);
  await page.getByRole('button', { name: DealControl.newGame, exact: true }).click();
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(8);
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(8);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption('6');
  await page.reload();
  await expect(page.locator('.card')).toHaveCount(36);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption('4');
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(8);
});

test('valid board loads save their size while invalid loads keep that preference', async ({
  page,
  gameURL,
}) => {
  await loadFixedBoard(page, gameURL);
  await page.locator('summary').click();
  const input = page.getByLabel(ReproductionControl.board, { exact: true });
  await input.fill('np1-6-1');
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await input.fill('invalid');
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await page.reload();
  await expect(page.locator('.card')).toHaveCount(36);
});

test('malformed stored preferences fall back to a playable default game', async ({
  page,
  gameURL,
}) => {
  await page.addInitScript((key) => localStorage.setItem(key, '{'), PREFERENCES_KEY);
  await page.goto(gameURL);
  await expect(page.locator('.card')).toHaveCount(16);
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { StatusLabel } from '../src/game/status/status-labels.ts';
import { loadTimedBoard } from './game-fixture.ts';
import { uiSnapshot } from './ui-snapshot.ts';

test('completion shows final moves and time and keeps the completed clock stopped', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const expected = await uiSnapshot();
  await expect(page.locator('.stats dd').nth(3)).toHaveText(expected.bestNone);
  const firstPair = EXAMPLE_PAIRS[0];
  await page.locator('.card').nth(firstPair[0]).click();
  await page.clock.runFor(3000);
  await page.locator('.card').nth(firstPair[1]).click();
  for (const pair of EXAMPLE_PAIRS.slice(1))
    for (const index of pair) await page.locator('.card').nth(index).click();
  const banner = page.locator('.victory');
  await expect(banner).toHaveText(expected.winBanner);
  await expect(banner, 'V06 banner text').toHaveCSS('color', 'rgb(244, 246, 255)');
  await expect(banner, 'V06 banner border').toHaveCSS('border-color', 'rgb(117, 124, 154)');
  await expect(page.getByRole('status')).toHaveText(expected.winningResult);
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(EXAMPLE_PAIRS.length);
  const elapsed = await page
    .locator('.stats > div')
    .filter({ has: page.getByText(StatusLabel.time, { exact: true }) })
    .locator('dd')
    .textContent();
  await page.clock.runFor(5000);
  expect(
    await page
      .locator('.stats > div')
      .filter({ has: page.getByText(StatusLabel.time, { exact: true }) })
      .locator('dd')
      .textContent(),
  ).toBe(elapsed);
});
import { readFile } from 'node:fs/promises';
import { isJsonObject } from '../src/game/saved-format.ts';
import { SNAPSHOT_PATH } from './game-fixture.ts';

export async function uiSnapshot() {
  const value: unknown = JSON.parse(await readFile(SNAPSHOT_PATH, 'utf8'));
  if (
    !isJsonObject(value) ||
    typeof value.bestNone !== 'string' ||
    typeof value.winBanner !== 'string' ||
    typeof value.mismatch !== 'string' ||
    typeof value.winningResult !== 'string'
  ) {
    throw new Error('Expected the reviewed UI snapshot.');
  }
  return {
    bestNone: value.bestNone,
    winBanner: value.winBanner,
    mismatch: value.mismatch,
    winningResult: value.winningResult,
  };
}
